<?php
require_once __DIR__.'/../includes/authorization.php';require_role('admin');require_once __DIR__.'/../includes/Repositories/ReviewRepository.php';$repo=new ReviewRepository();
if(is_post()){if(!verify_csrf()){flash('error','Sesi formulir tidak valid.');redirect(page_url('admin-reviews'));}$id=filter_input(INPUT_POST,'review_id',FILTER_VALIDATE_INT);if($id){$repo->delete((int)$id);flash('success','Ulasan dihapus dari moderasi.');}redirect(page_url('admin-reviews'));}
$reviews=$repo->all();$pageTitle='Kelola Ulasan';require __DIR__.'/../includes/header.php';
?><section class="section-padding page-section"><div class="container"><div class="page-toolbar"><?=back_link('admin-dashboard','Kembali ke dashboard admin')?></div><div class="section-heading mb-4"><span class="eyebrow">Admin</span><h2>Moderasi <em>ulasan.</em></h2><p class="text-muted">Ulasan hanya dapat dibuat customer setelah pembelian selesai.</p></div><?php if(!$reviews):?><div class="glass-card empty-state"><span><i class="bi bi-chat-square-text"></i></span><h2>Belum ada ulasan</h2></div><?php endif;?><?php foreach($reviews as $r):?><div class="glass-card p-4 mb-3"><div class="d-flex justify-content-between gap-3"><div><strong><?=e($r['product_name'])?></strong><div class="small text-muted"><?=e($r['buyer_name'])?> · <?=intval($r['rating'])?>/5</div></div><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="review_id" value="<?=intval($r['id'])?>"><button class="btn btn-outline-danger btn-sm">Hapus</button></form></div><p class="mt-3 mb-0"><?=nl2br(e($r['review_text']))?></p></div><?php endforeach;?></div></section><?php require __DIR__.'/../includes/footer.php'; ?>